39	export interface SessionConfig {
40	  /**
41	   * Private key used to seal session tokens. Must be at least 32 characters.
42	   *
43	   * Its entropy is the security boundary: a stolen cookie can be brute-forced
44	   * offline, so generate this from a cryptographically random source (e.g.
45	   * `crypto.randomBytes(32).toString("base64")`) — a guessable passphrase is
46	   * unsafe even at 32+ characters.
47	   */
48	  password: string;
49	  /**
50	   * Absolute session lifetime in seconds, counted from when the session was
51	   * created. Reached regardless of how active the user is.
52	   */
53	  maxAge?: number;
54	  /**
55	   * Sliding session lifetime in seconds, counted from the last request. An
56	   * active user stays signed in; an idle one is signed out after this long.
57	   *
58	   * Equivalent to `rolling` in express-session and koa-session, but with its own
59	   * duration instead of reinterpreting `maxAge` — so `maxAge` remains available
60	   * as an absolute cap on top of the idle window rather than being replaced.
61	   *
62	   * H3 moves the window forward by resealing the session cookie with the reseal
63	   * time stamped into it as `lastSeenAt`; `createdAt` is untouched. Only
64	   * cookie-based sessions slide: a session read from the session header cannot
65	   * be resealed, so it expires `idleTimeout` after its seal was issued.
66	   *
67	   * The reseal is throttled to once per half window (writing the session
68	   * reseals it too, and counts), so `lastSeenAt` can trail the last request by
69	   * up to half of `idleTimeout`. An idle session is therefore signed out
70	   * between `idleTimeout / 2` and `idleTimeout` after the last request — never
71	   * later, and never while the user keeps making requests.
72	   */
73	  idleTimeout?: number;
74	  /** default is h3 */
75	  name?: string;
76	  /** Default is secure, httpOnly, sameSite lax, / */
77	  cookie?: false | (CookieSerializeOptions & { chunkMaxLength?: number });
78	  /** Default is x-h3-session / x-{name}-session */
79	  sessionHeader?: false | string;
80	  /**
81	   * Overrides for the iron seal (algorithms, PBKDF2 iterations, TTL, clock skew).
82	   *
83	   * `SealOptions` has no optional fields, so an override must specify all of
84	   * them. Session expiration is enforced by `maxAge`/`idleTimeout` independently
85	   * of the seal `ttl` set here, so a shorter or zeroed `ttl` cannot extend a
86	   * session beyond those limits.
87	   */
88	  seal?: SealOptions;
89	  /**
90	   * Set to `false` to reject sessions sealed with the legacy default of 1
91	   * PBKDF2 iteration instead of unsealing and resealing them.
92	   *
93	   * @deprecated The legacy seal fallback (and this option) will be removed in v3.
94	   */
95	  legacySealFallback?: boolean;
96	  crypto?: Crypto;
97	  /** Default is Crypto.randomUUID */
98	  generateId?: () => string;
99	}
100	
101	/**
102	 * Create a session manager for the current request.
103	 *
104	 * Starts a session if the request does not carry one, persisting it so its id
105	 * is stable across requests. Use {@link getSession} to read a session without
106	 * starting one.
107	 */
108	export async function useSession<T extends SessionData = SessionData>(
109	  event: HTTPEvent,
110	  config: SessionConfig,
111	): Promise<SessionManager<T>> {
112	  // Create a synced wrapper around the session
113	  const sessionName = config.name || DEFAULT_SESSION_NAME;
114	  // Force init: persist a session created during this request so its id is stable
115	  const session = await getSession(event, config);
116	  if (session[kSessionNew]) {
117	    await updateSession(event, config);
118	  }
119	  const sessionManager = {
120	    get id() {
121	      const context = getEventContext<H3EventContext>(event);
122	      return context?.sessions?.[sessionName]?.id;
123	    },
124	    get data() {
125	      const context = getEventContext<H3EventContext>(event);
126	      return (context.sessions?.[sessionName]?.data || new EmptyObject()) as T;
127	    },
128	    update: async (update: SessionUpdate<T>) => {
129	      await updateSession<T>(event, config, update);
130	      return sessionManager;
131	    },
132	    clear: () => {
133	      clearSession(event, config);
134	      return Promise.resolve(sessionManager);
135	    },
136	  };
137	  return sessionManager;
138	}
139	
140	/**
141	 * Get the session for the current request.
142	 *
143	 * A request without a session gets a new one initialized in memory only — no
144	 * `Set-Cookie` is issued until something is stored with {@link updateSession},
145	 * so reading the session (an auth check, for example) does not start one for
146	 * anonymous visitors. Its `id` is therefore only stable across requests once
147	 * the session has been written; use {@link useSession} to start one eagerly.
148	 */
149	export async function getSession<T extends SessionData = SessionData>(
150	  event: HTTPEvent,
151	  config: SessionConfig,
152	): Promise<Session<T>> {
153	  const sessionName = config.name || DEFAULT_SESSION_NAME;
154	
155	  const context = getEventContext<H3EventContext>(event);
156	
157	  // Return existing session if available
158	  if (!context.sessions) {
159	    context.sessions = new EmptyObject();
160	  }
161	  // Wait for existing session to load
162	  const existingSession = context.sessions![sessionName] as Session<T>;
163	  if (existingSession) {
164	    return existingSession[kGetSession] || existingSession;
165	  }
166	
167	  // Prepare an empty session object and store in context
168	  const session: Session<T> = {
169	    id: "",
170	    createdAt: 0,
171	    data: new EmptyObject(),
172	  };
173	  context.sessions![sessionName] = session;
174	
175	  // Try to load session
176	  let sealedSession: string | undefined;
177	  // Try header first
178	  if (config.sessionHeader !== false) {
179	    const headerName =
180	      typeof config.sessionHeader === "string"
181	        ? config.sessionHeader.toLowerCase()
182	        : `x-${sessionName.toLowerCase()}-session`;
183	    const headerValue = event.req.headers.get(headerName);
184	    if (typeof headerValue === "string") {
185	      sealedSession = headerValue;
186	    }
187	  }
188	  // Fallback to cookies
189	  let sessionFromCookie = false;
190	  if (!sealedSession) {
191	    sealedSession = getChunkedCookie(event, sessionName);
192	    sessionFromCookie = true;
193	  }
194	  if (sealedSession) {
195	    // Unseal session data from cookie
196	    const promise = unsealSession(event, config, sealedSession)
197	      .catch(() => {})
198	      .then(async (unsealed) => {
199	        const legacySeal = unsealed && (unsealed as any)[kLegacySeal];
200	        if (legacySeal) {
201	          delete (unsealed as any)[kLegacySeal];
202	        }
203	        // `JSON.parse` yields plain objects; keep live data prototype-free so a
204	        // `__proto__` key in a later `updateSession` cannot swap its prototype.
205	        if (unsealed?.data) {
206	          unsealed.data = Object.assign(new EmptyObject(), unsealed.data);
207	        }
208	        Object.assign(session, unsealed);
209	        delete context.sessions![sessionName][kGetSession];
210	        // Proactively reseal legacy cookies with the current seal options, and
211	        // reseal under idleTimeout to slide the window (see `shouldSlide`). A
212	        // session that failed to unseal has no id and is replaced below, so
213	        // resealing it here is wasted work.
214	        if (session.id && sessionFromCookie && (legacySeal || shouldSlide(session, config))) {
215	          await updateSession(event, config);
216	        }
217	        return session as Session<T>;
218	      });
219	    context.sessions![sessionName][kGetSession] = promise;
220	    await promise;
221	  }
222	
223	  // New session: initialize in memory only. It is persisted by the first
224	  // `updateSession` (or by `useSession`, which force-inits).
225	  if (!session.id) {
226	    session.id = config.generateId?.() ?? (config.crypto || crypto).randomUUID();
227	    session.createdAt = Date.now();
228	    session[kSessionNew] = true;
229	  }
230	
231	  return session;
232	}
233	
234	type SessionUpdate<T extends SessionData = SessionData> =
235	  | Partial<SessionData<T>>
236	  | ((oldData: SessionData<T>) => Partial<SessionData<T>> | undefined);
237	
238	/**
239	 * Update the session data for the current request.
240	 */
241	export async function updateSession<T extends SessionData = SessionData>(
242	  event: HTTPEvent,
243	  config: SessionConfig,
244	  update?: SessionUpdate<T>,
245	): Promise<Session<T>> {
246	  const sessionName = config.name || DEFAULT_SESSION_NAME;
247	
248	  // Access current session
249	  const context = getEventContext<H3EventContext>(event);
250	  const session: Session<T> =
251	    (context.sessions?.[sessionName] as Session<T>) || (await getSession<T>(event, config));
252	
253	  // Update session data if provided
254	  if (typeof update === "function") {
255	    update = update(session.data);
256	  }
257	  if (update) {
258	    Object.assign(session.data, update);
259	  }
260	
261	  // Persisted (or persistence is disabled by config): no longer a fresh session
262	  // awaiting its first write.
263	  delete session[kSessionNew];
264	
265	  // Seal and store in cookie
266	  if (config.cookie !== false && (event as H3Event).res) {
267	    const sealed = await sealSession(event, config);
268	    setChunkedCookie(event as H3Event, sessionName, sealed, {
269	      ...DEFAULT_SESSION_COOKIE,
270	      expires: sessionExpires(session, config),
271	      ...config.cookie,
272	    });
273	    stageSessionErrCookies(event as H3Event, sessionName);
274	  }
275	
276	  return session;
277	}
278	
279	/**
280	 * Encrypt and sign the session data for the current request.
281	 */
282	export async function sealSession<T extends SessionData = SessionData>(
283	  event: HTTPEvent,
284	  config: SessionConfig,
285	): Promise<string> {
286	  const sessionName = config.name || DEFAULT_SESSION_NAME;
287	
288	  // Access current session
289	  const context = getEventContext<H3EventContext>(event);
290	  const session: Session<T> =
291	    (context.sessions?.[sessionName] as Session<T>) || (await getSession<T>(event, config));
292	
293	  if (config.idleTimeout) {
294	    // The idle window is measured from the last reseal rather than from
295	    // createdAt. Only stamped when enabled, so the default sealed payload is
296	    // unchanged.
297	    session.lastSeenAt = Date.now();
298	  }
299	
300	  const sealed = await seal(session, config.password, {
301	    ...sealDefaults,
302	    ttl: (config.maxAge || config.idleTimeout || 0) * 1000,
303	    ...config.seal,
304	  });
305	
306	  return sealed;
307	}
308	
309	/**
310	 * Decrypt and verify the session data for the current request.
311	 */
312	export async function unsealSession(
313	  _event: HTTPEvent,
314	  config: SessionConfig,
315	  sealed: string,
316	): Promise<Partial<Session>> {
317	  const sealOptions = {
318	    ...sealDefaults,
319	    ttl: (config.maxAge || config.idleTimeout || 0) * 1000,
320	    ...config.seal,
321	  };
322	  let unsealed: Partial<Session>;
323	  try {
324	    unsealed = (await unseal(sealed, config.password, sealOptions)) as Partial<Session>;
325	  } catch (error) {
326	    // TODO: Remove this fallback (and `legacySealFallback`) in v3. Removing it
327	    // in a v2 release would invalidate existing sessions sealed with 1 iteration.
328	    // Sessions sealed before the default PBKDF2 iterations were raised from 1
329	    // to 8192 fail HMAC verification; retry with the legacy count so existing
330	    // sessions survive the upgrade (getSession reseals them with the current
331	    // options).
332	    if (
333	      config.legacySealFallback === false ||
334	      sealOptions.integrity.iterations === 1 ||
335	      !(error instanceof Error) ||
336	      error.message !== "Bad hmac value"
337	    ) {
338	      throw error;
339	    }
340	    unsealed = (await unseal(sealed, config.password, {
341	      ...sealOptions,
342	      encryption: { ...sealOptions.encryption, iterations: 1 },
343	      integrity: { ...sealOptions.integrity, iterations: 1 },
344	    })) as Partial<Session>;
345	    if (unsealed) {
346	      (unsealed as any)[kLegacySeal] = true;
347	    }
348	  }
349	  // Absolute lifetime, counted from when the session was created
350	  if (config.maxAge) {
351	    const age = Date.now() - (unsealed.createdAt || Number.NEGATIVE_INFINITY);
352	    if (age > config.maxAge * 1000) {
353	      throw new Error("Session expired!");
354	    }
355	  }
356	  // Idle window, counted from the last reseal. Sessions sealed before
357	  // idleTimeout was configured, and sessions read from the session header (which
358	  // are never resealed), fall back to createdAt
359	  if (config.idleTimeout) {
360	    const idle =
361	      Date.now() - (unsealed.lastSeenAt || unsealed.createdAt || Number.NEGATIVE_INFINITY);
362	    if (idle > config.idleTimeout * 1000) {
363	      throw new Error("Session expired!");
364	    }
365	  }
366	  return unsealed;
367	}
368	
369	/**
370	 * Clear the session data for the current request.
371	 */
372	export function clearSession(event: HTTPEvent, config: Partial<SessionConfig>): Promise<void> {
373	  const context = getEventContext<H3EventContext>(event);
374	  const sessionName = config.name || DEFAULT_SESSION_NAME;
375	  if (context.sessions?.[sessionName]) {
376	    delete context.sessions![sessionName];
377	  }
378	  if ((event as H3Event).res && config.cookie !== false) {
379	    deleteChunkedCookie(event as H3Event, sessionName, {
380	      ...DEFAULT_SESSION_COOKIE,
381	      ...config.cookie,
382	    });
383	    stageSessionErrCookies(event as H3Event, sessionName);
384	  }
385	  return Promise.resolve();
386	}
387	
388	/**
389	 * Fraction of the idle window that has to be used up before `getSession`
390	 * reseals to slide it. See {@link shouldSlide}.
391	 */
392	const SLIDE_THRESHOLD = 0.5;
393	
394	/**
395	 * Whether reading the session should also reseal it to move the idle window
396	 * forward.
397	 *
398	 * Sliding the window means writing `lastSeenAt` back into the cookie, and that
399	 * seal is by far the most expensive thing a session does. Doing it on every
400	 * request also wastes it twice over on a request that writes the session: the
401	 * handler's `update()` reseals with the same fresh `lastSeenAt`, and
402	 * `setCookie`'s dedupe drops the first `Set-Cookie` anyway.
403	 *
404	 * So reseal only once the window is more than half used. Any `updateSession`
405	 * (from a handler write, or from the reseal itself) restamps `lastSeenAt`, so
406	 * writes keep sliding the window for free and a request that both reads and
407	 * writes almost never seals twice.
408	 *
409	 * The trade-off is granularity, in the safe direction: `lastSeenAt` can trail
410	 * the last request by up to half the window, so an idle session is signed out
411	 * somewhere between `idleTimeout / 2` and `idleTimeout` after the last request,
412	 * never later.
413	 */
414	function shouldSlide(session: Session<any>, config: SessionConfig): boolean {
415	  if (!config.idleTimeout) {
416	    return false;
417	  }
418	  // Sessions sealed before `idleTimeout` was configured have no `lastSeenAt`
419	  const lastSeenAt = session.lastSeenAt || session.createdAt || 0;
420	  return Date.now() - lastSeenAt > config.idleTimeout * 1000 * SLIDE_THRESHOLD;
421	}
422	
423	/**
424	 * Mirror this session's `Set-Cookie` headers into `event.res.errHeaders`.
425	 *
426	 * Error responses only receive headers explicitly staged as `errHeaders`, so
427	 * without this a request that throws drops the session cookie entirely: a
428	 * session created during that request is lost, and under `idleTimeout` the idle
429	 * window fails to slide even though the user was active.
430	 *
431	 * Re-staged from scratch on every write so the latest state wins — in
432	 * particular, a `clearSession` after a reseal must not leave the stale reseal
433	 * cookie behind to resurrect the session on an error response.
434	 */
435	function stageSessionErrCookies(event: H3Event, sessionName: string): void {
436	  // Chunks are stored as `{name}.{n}` by `setChunkedCookie`
437	  const isSessionCookie = (cookie: string) =>
438	    cookie.startsWith(`${sessionName}=`) || cookie.startsWith(`${sessionName}.`);
439	
440	  const errHeaders = event.res.errHeaders;
441	  const staged = [
442	    ...errHeaders.getSetCookie().filter((cookie) => !isSessionCookie(cookie)),
443	    ...event.res.headers.getSetCookie().filter((cookie) => isSessionCookie(cookie)),
444	  ];
445	  errHeaders.delete("set-cookie");
446	  for (const cookie of staged) {
447	    errHeaders.append("set-cookie", cookie);
448	  }
449	}
450	
451	/**
452	 * Cookie expiry: whichever of the absolute lifetime and the idle window runs out
453	 * first, or none if neither is configured.
454	 */
455	function sessionExpires(session: Session<any>, config: SessionConfig): Date | undefined {
456	  const times: number[] = [];
457	  if (config.maxAge) {
458	    times.push(session.createdAt + config.maxAge * 1000);
459	  }
460	  if (config.idleTimeout) {
461	    times.push((session.lastSeenAt || session.createdAt) + config.idleTimeout * 1000);
462	  }
463	  return times.length > 0 ? new Date(Math.min(...times)) : undefined;
464	}
